+    // Parse digits before decimal point
+    while (p < end && *p >= '0' && *p <= '9') {
+        if (total_digits < MAX_FAST_DIGITS) {
+            mantissa = mantissa * 10 + (*p - '0');
+        }
+        ++total_digits;
+        ++p;
+    }
+    
+    // Parse fractional part
+    if (p < end && *p == '.') {
+        has_dot = true;
+        ++p;
+        while (p < end && *p >= '0' && *p <= '9') {
+            if (total_digits < MAX_FAST_DIGITS) {
