+            }
+            ++total_digits;
+            ++digits_after_dot;
+            ++p;
+        }
+    }
+    
+    // Parse exponent
+    if (p < end && (*p == 'e' || *p == 'E')) {
+        has_exp = true;
+        ++p;
+        bool exp_neg = false;
+        if (p < end && *p == '+') {
+            ++p;
+        } else if (p < end && *p == '-') {
